  "code": "from flask import Flask, request, Response

app = Flask(__name__)

@app.route('/')
def route():
    content_type = request.args.get('content_type', 'text/plain')
    response = Response(content_type=content_type)
    response.headers['Content-Type'] = content_type
    return response"
